[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --bg2: #181b23;
    --bg3: #1e2130;
    --border: #2a2e42;
    --accent: #e8c14a;
    --accent2: #5b9cf6;
    --accent3: #4ecdc4;
    --accent4: #ff6b6b;
    --accent5: #a78bfa;
    --text: #e8eaf0;
    --text-muted: #8b90a7;
    --green: #4ade80;
    --red: #f87171;
    --font: 'Inter', system-ui, -apple-system, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: var(--bg); color: var(--text); font-family: var(--font); font-size: 14px; line-height: 1.6; }
  a { color: var(--accent2); }

  /* Layout */
  .page { max-width: 1200px; margin: 0 auto; padding: 40px 24px; }

  /* Header */
  .report-header { border-bottom: 1px solid var(--border); padding-bottom: 32px; margin-bottom: 40px; }
  .report-header .label { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); font-weight: 600; margin-bottom: 8px; }
  .report-header h1 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.2; }
  .report-header .subtitle { margin-top: 10px; color: var(--text-muted); font-size: 15px; max-width: 700px; }
  .report-header .meta { margin-top: 16px; display: flex; gap: 24px; flex-wrap: wrap; }
  .report-header .meta-item { font-size: 12px; color: var(--text-muted); }
  .report-header .meta-item strong { color: var(--text); }

  /* KPI Cards */
  .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 48px; }
  .kpi-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 10px; padding: 20px 22px; position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent-color, var(--accent)); }
  .kpi-card .kpi-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); margin-bottom: 10px; }
  .kpi-card .kpi-value { font-size: 30px; font-weight: 700; color: var(--text); line-height: 1; }
  .kpi-card .kpi-sub { font-size: 12px; color: var(--text-muted); margin-top: 6px; }
  .kpi-card .kpi-badge { display: inline-block; font-size: 11px; font-weight: 600; padding: 2px 7px; border-radius: 4px; margin-top: 8px; }
  .badge-green { background: rgba(74,222,128,0.12); color: var(--green); }
  .badge-yellow { background: rgba(232,193,74,0.12); color: var(--accent); }

  /* Sections */
  section { margin-bottom: 56px; }
  .section-header { margin-bottom: 24px; }
  .section-header .section-num { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); font-weight: 600; }
  .section-header h2 { font-size: 22px; font-weight: 700; margin-top: 4px; }
  .section-header p { color: var(--text-muted); margin-top: 6px; max-width: 800px; font-size: 14px; }

  /* Charts */
  .chart-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(380px, 1fr)); gap: 20px; margin-bottom: 24px; }
  .chart-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 10px; padding: 24px; }
  .chart-card h3 { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
  .chart-card .chart-desc { font-size: 12px; color: var(--text-muted); margin-bottom: 18px; }
  .chart-wrap { position: relative; }

  /* Tables */
  .table-wrap { overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  thead th { background: var(--bg3); color: var(--text-muted); font-size: 11px; text-transform: uppercase; letter-spacing: 1px; padding: 10px 14px; text-align: left; border-bottom: 1px solid var(--border); }
  tbody tr { border-bottom: 1px solid var(--border); transition: background 0.1s; }
  tbody tr:hover { background: var(--bg3); }
  tbody td { padding: 10px 14px; color: var(--text); }
  tbody td.num { font-variant-numeric: tabular-nums; }
  .tag { display: inline-block; font-size: 11px; padding: 2px 8px; border-radius: 4px; font-weight: 600; }
  .tag-ds { background: rgba(232,193,74,0.12); color: var(--accent); }
  .tag-vnds { background: rgba(91,156,246,0.12); color: var(--accent2); }
  .tag-used { background: rgba(248,113,113,0.12); color: var(--red); }
  .tag-pos { background: rgba(74,222,128,0.12); color: var(--green); }
  .tag-neg { background: rgba(248,113,113,0.12); color: var(--red); }

  /* Inline stats */
  .stat-row { display: flex; gap: 32px; flex-wrap: wrap; margin-top: 20px; }
  .stat-item { }
  .stat-item .stat-val { font-size: 22px; font-weight: 700; }
  .stat-item .stat-lbl { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

  /* Insight boxes */
  .insight { background: var(--bg2); border-left: 3px solid var(--accent); border-radius: 6px; padding: 14px 18px; margin: 16px 0; font-size: 13px; }
  .insight strong { color: var(--accent); }
  .insight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin: 20px 0; }

  /* Recommendations */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; }
  .rec-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 10px; padding: 20px; }
  .rec-card .rec-icon { font-size: 22px; margin-bottom: 10px; }
  .rec-card h4 { font-size: 14px; font-weight: 700; margin-bottom: 8px; color: var(--accent); }
  .rec-card p { font-size: 13px; color: var(--text-muted); line-height: 1.55; }
  .rec-card ul { margin-top: 8px; padding-left: 16px; }
  .rec-card li { font-size: 12px; color: var(--text-muted); margin-bottom: 4px; }

  /* Condition matrix */
  .cond-matrix { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px; margin: 20px 0; }
  .cond-card { border-radius: 10px; padding: 20px; border: 1px solid var(--border); }
  .cond-card.ds { border-top: 3px solid var(--accent); background: linear-gradient(160deg, rgba(232,193,74,0.05), var(--bg2)); }
  .cond-card.vnds { border-top: 3px solid var(--accent2); background: linear-gradient(160deg, rgba(91,156,246,0.05), var(--bg2)); }
  .cond-card.used { border-top: 3px solid var(--red); background: linear-gradient(160deg, rgba(248,113,113,0.05), var(--bg2)); }
  .cond-card h4 { font-size: 13px; font-weight: 700; margin-bottom: 14px; }
  .cond-stat { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 13px; border-bottom: 1px solid var(--border); padding-bottom: 8px; }
  .cond-stat:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }
  .cond-stat .cs-lbl { color: var(--text-muted); }
  .cond-stat .cs-val { font-weight: 700; }

  /* Footer */
  .report-footer { border-top: 1px solid var(--border); padding-top: 24px; margin-top: 48px; display: flex; justify-content: space-between; align-items: center; flex-wrap: gap; }
  .report-footer p { font-size: 12px; color: var(--text-muted); }

  /* Bar inline */
  .bar-bg { background: var(--border); border-radius: 3px; height: 6px; margin-top: 5px; }
  .bar-fill { height: 6px; border-radius: 3px; }

  @media (max-width: 640px) {
    .cond-matrix { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .chart-grid { grid-template-columns: 1fr; }
    .rec-grid { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
<div class="page">

  <!-- ===== HEADER ===== -->
  <header class="report-header">
    <div class="label">Market Intelligence Report</div>
    <h1>Air Jordan Sneaker Resale Market<br>Analysis (2023–2026)</h1>
    <p class="subtitle">A comprehensive analysis of 5,000 secondary-market transactions examining pricing dynamics, profit margins, inventory velocity, and channel performance across models, colorways, and condition tiers.</p>
    <div class="meta">
      <div class="meta-item"><strong>Transactions Analyzed:</strong> 5,000</div>
      <div class="meta-item"><strong>Date Range:</strong> January 2023 – September 2025</div>
      <div class="meta-item"><strong>Models Covered:</strong> 5 Air Jordan silhouettes</div>
      <div class="meta-item"><strong>Sales Channels:</strong> 5 platforms</div>
      <div class="meta-item"><strong>Colorways:</strong> 9 colorways</div>
      <div class="meta-item"><strong>Report Generated:</strong> April 2026</div>
    </div>
  </header>

  <!-- ===== KPI DASHBOARD ===== -->
  <div class="kpi-grid">
    <div class="kpi-card" style="--accent-color: #e8c14a">
      <div class="kpi-label">Avg Profit Margin</div>
      <div class="kpi-value">$82.06</div>
      <div class="kpi-sub">Per transaction, across all conditions</div>
      <span class="kpi-badge badge-green">+Deadstock drives $264 avg</span>
    </div>
    <div class="kpi-card" style="--accent-color: #5b9cf6">
      <div class="kpi-label">Resale Premium Rate</div>
      <div class="kpi-value">61.3%</div>
      <div class="kpi-sub">Transactions above retail price</div>
      <span class="kpi-badge badge-yellow">3-yr range: 60.7%–63.1%</span>
    </div>
    <div class="kpi-card" style="--accent-color: #4ecdc4">
      <div class="kpi-label">Avg Days in Inventory</div>
      <div class="kpi-value">22.5</div>
      <div class="kpi-sub">Days from acquisition to sale</div>
      <span class="kpi-badge badge-green">Digital platforms: 7–8 days</span>
    </div>
    <div class="kpi-card" style="--accent-color: #a78bfa">
      <div class="kpi-label">Resale-to-Retail Ratio</div>
      <div class="kpi-value">1.43x</div>
      <div class="kpi-sub">Avg resale vs. MSRP multiplier</div>
      <span class="kpi-badge badge-yellow">Deadstock: ~2.3x retail</span>
    </div>
    <div class="kpi-card" style="--accent-color: #ff6b6b">
      <div class="kpi-label">Top Colorway Margin</div>
      <div class="kpi-value">$89.23</div>
      <div class="kpi-sub">Pine Green — highest avg across 566 tx</div>
      <span class="kpi-badge badge-green">Military Blue 2nd: $87.55</span>
    </div>
  </div>

  <!-- ===== SECTION 1: MARKET OVERVIEW ===== -->
  <section id="market-overview">
    <div class="section-header">
      <div class="section-num">Section 01</div>
      <h2>Market Overview &amp; Transaction Summary</h2>
      <p>High-level summary of the 5,000-transaction dataset: price ranges, margin distribution, and the overall health of the Air Jordan resale ecosystem.</p>
    </div>

    <div class="chart-grid">
      <div class="chart-card" style="grid-column: span 2;">
        <h3>Profit Margin Distribution</h3>
        <div class="chart-desc">Count of transactions by profit margin bucket — illustrates the bimodal nature of the market (heavy losses on Used vs. strong gains on Deadstock).</div>
        <div class="chart-wrap"><canvas id="marginDistChart" height="120"></canvas></div>
      </div>
    </div>

    <div class="insight-grid">
      <div class="insight">
        <strong>Bimodal Market Structure:</strong> The distribution is distinctly bimodal. 1,933 transactions (38.7%) clear below retail, concentrated in Used-condition shoes. The 3,067 above-retail transactions (61.3%) are almost entirely Deadstock and a subset of VNDS inventory.
      </div>
      <div class="insight">
        <strong>High-Upside Tail:</strong> 1,047 transactions (21.0%) exceed $200 profit. These outsized wins — concentrated in Deadstock Air Jordan 11 Retro, 3 Retro, and 4 Retro — pull the overall average well above median, making mean margin a misleading signal without condition segmentation.
      </div>
      <div class="insight">
        <strong>Below-Retail Floor:</strong> 96 transactions (1.9%) exceed -$100 loss. All are Used-condition shoes in less-hyped colorways sold via traditional retail channels. The maximum downside on Used inventory averages -$57.66, setting a clear cost-of-goods floor for sourcing decisions.
      </div>
    </div>

    <div style="margin-top: 28px;">
      <div class="chart-card">
        <h3>Retail vs. Resale Price by Condition</h3>
        <div class="chart-desc">Average retail MSRP vs. average resale price stratified by condition tier.</div>
        <div class="chart-wrap"><canvas id="retailVsResaleChart" height="160"></canvas></div>
      </div>
    </div>
  </section>

  <!-- ===== SECTION 2: MODEL & COLORWAY ===== -->
  <section id="model-colorway-analysis">
    <div class="section-header">
      <div class="section-num">Section 02</div>
      <h2>Performance by Shoe Model &amp; Colorway</h2>
      <p>Ranking Air Jordan silhouettes and colorways by average resale price, profit margin, and transaction volume to identify the highest-premium and below-retail segments.</p>
    </div>

    <div class="chart-grid">
      <div class="chart-card">
        <h3>Avg Profit Margin by Model</h3>
        <div class="chart-desc">Mean USD margin per shoe model across all conditions.</div>
        <div class="chart-wrap"><canvas id="modelMarginChart" height="200"></canvas></div>
      </div>
      <div class="chart-card">
        <h3>Avg Resale Price by Model</h3>
        <div class="chart-desc">Mean resale clearing price vs. mean retail MSRP.</div>
        <div class="chart-wrap"><canvas id="modelResaleChart" height="200"></canvas></div>
      </div>
    </div>

    <div style="margin-top: 24px;">
      <h3 style="font-size:15px; margin-bottom:16px; font-weight:700;">Model Performance Summary</h3>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Model</th>
              <th>Transactions</th>
              <th>Avg Resale Price</th>
              <th>Avg Profit Margin</th>
              <th>Resale/Retail Ratio</th>
              <th>Avg Days in Inventory</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td><strong>Air Jordan 11 Retro</strong></td>
              <td class="num">973</td>
              <td class="num">$327.31</td>
              <td class="num"><span class="tag tag-pos">$99.84</span></td>
              <td class="num">1.44x</td>
              <td class="num">21.4</td>
            </tr>
            <tr>
              <td><strong>Air Jordan 4 Retro</strong></td>
              <td class="num">1,044</td>
              <td class="num">$313.25</td>
              <td class="num"><span class="tag tag-pos">$95.76</span></td>
              <td class="num">1.44x</td>
              <td class="num">22.8</td>
            </tr>
            <tr>
              <td><strong>Air Jordan 3 Retro</strong></td>
              <td class="num">1,037</td>
              <td class="num">$287.82</td>
              <td class="num"><span class="tag tag-pos">$82.79</span></td>
              <td class="num">1.40x</td>
              <td class="num">22.3</td>
            </tr>
            <tr>
              <td><strong>Air Jordan 1 High</strong></td>
              <td class="num">926</td>
              <td class="num">$262.18</td>
              <td class="num"><span class="tag tag-pos">$81.85</span></td>
              <td class="num">1.45x</td>
              <td class="num">22.7</td>
            </tr>
            <tr>
              <td><strong>Air Jordan 1 Low</strong></td>
              <td class="num">1,020</td>
              <td class="num">$175.88</td>
              <td class="num"><span class="tag tag-pos">$50.52</span></td>
              <td class="num">1.40x</td>
              <td class="num">23.1</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>

    <div style="margin-top: 32px;">
      <h3 style="font-size:15px; margin-bottom:16px; font-weight:700;">Colorway Performance Ranking</h3>
      <div class="chart-card">
        <h3>Avg Profit Margin by Colorway</h3>
        <div class="chart-desc">Ranked by average margin across all models and conditions. Pine Green leads; Black Cat trails.</div>
        <div class="chart-wrap"><canvas id="colorwayChart" height="180"></canvas></div>
      </div>

      <div class="table-wrap" style="margin-top:20px;">
        <table>
          <thead>
            <tr>
              <th>Rank</th>
              <th>Colorway</th>
              <th>Transactions</th>
              <th>Avg Resale Price</th>
              <th>Avg Profit Margin</th>
              <th>Above-Retail Rate</th>
              <th>Avg Days in Inventory</th>
            </tr>
